int main(){int t;scanf("%d",&t);while(t--){int n,m;scanf("%d %d",&n,&m);int N=n+m+1;vector<long long>v[2];v[0].resize(N);v[1].resize(N);
 for(auto&x:v[0])scanf("%lld",&x);for(auto&x:v[1])scanf("%lld",&x);
 int cap[2]={n,m};vector<int>role(N),pref(N);long long base=0;
 for(int i=0;i<N-1;i++){pref[i]=v[0][i]>v[1][i]?0:1;int r=pref[i];if(cap[r]==0)r^=1;cap[r]--;role[i]=r;base+=v[r][i];}
 vector<array<int,2>>nx(N);
 array<int,2>cur={-1,-1};
 for(int i=N-2;i>=0;i--){nx[i]=cur;if(role[i]!=pref[i])cur[pref[i]]=i;}
 int L=N-1;
 for(int i=0;i<N-1;i++){int r=role[i],j=nx[i][r];long long ans=base-v[r][i];
  if(j>=0)ans+=v[r][j]-v[r^1][j]+v[r^1][L];else ans+=v[r][L];printf("%lld ",ans);}
 printf("%lld\n",base);}}
